import { NextRequest, NextResponse } from 'next/server';

export function middleware(request: NextRequest) {
  const startTime = Date.now();
  const { method, url, headers } = request;
  const userAgent = headers.get('user-agent') || 'Unknown';
  const ip = headers.get('x-forwarded-for') || headers.get('x-real-ip') || request.ip || 'Unknown';

  // Log the incoming request
  console.log(`[${new Date().toISOString()}] ${method} ${url} - IP: ${ip} - User-Agent: ${userAgent}`);

  // Continue with the request
  const response = NextResponse.next();

  // Add timing information to response headers
  response.headers.set('X-Request-Start-Time', startTime.toString());
  response.headers.set('X-Request-Url', url);
  response.headers.set('X-Request-Method', method);

  // Log the response when it's sent
  response.headers.set('X-Request-Logged', 'true');

  return response;
}

// Configure which routes the middleware should run on
export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - api (API routes)
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     */
    '/((?!api|_next/static|_next/image|favicon.ico).*)',
  ],
};

